        {
            <span>Showing @StartItem–@EndItem of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string CurrentSort { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; } = 1;

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private int StartItem => TotalCount == 0 ? 0 : (Page - 1) * PageSize + 1;
    private int EndItem => Math.Min(Page * PageSize, TotalCount);

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "price_asc";
        await OnSortChanged.InvokeAsync(value);
    }
}
"}

{"path": "/tmp/sv-df0871c9a7d047c98d0c09a02ffe3033/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="GoToPrevious">
        Previous
    </button>

    @foreach (var page in PageNumbers)
    {
        <button class="btn-page @(page == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(page))">
            @page
        </button>
    }

    <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="GoToNext">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalPages { get; set; } = 1;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private IEnumerable<int> PageNumbers => Enumerable.Range(1, Math.Max(1, TotalPages));

    private async Task GoToPrevious()
    {
        if (CurrentPage > 1)
            await OnPageChanged.InvokeAsync(CurrentPage - 1);
    }

    private async Task GoToNext()
    {
        if (CurrentPage < TotalPages)
            await OnPageChanged.InvokeAsync(CurrentPage + 1);
    }

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }
}
"}

