+    font-size: 0.9rem;
+}
+
+.btn-add-to-cart:disabled {
+    background: #ccc;
+    cursor: not-allowed;
+}
+
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    gap: 0.5rem;
+    margin-top: 1.5rem;
+    padding: 1rem 0;
+}
+
+.btn-page {
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    background: white;
+    cursor: pointer;
+}
+
+.btn-page.active {
+    background: #0078d4;
+    color: white;
+    border-color: #0078d4;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+.empty-results {
+    text-align: center;
+    padding: 3rem 1rem;
+    color: #666;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 3rem 1rem;
+    color: #666;
+}
+
+.alert-error {
+    padding: 1rem;
+    background: #fdecea;
+    border: 1px solid #dc3545;
+    border-radius: 6px;
+    color: #721c24;
+    margin-bottom: 1rem;
+}
+
+.alert-error button {
+    margin-top: 0.5rem;
+    padding: 0.4rem 1rem;
+    background: #dc3545;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+

